//! The Go backend (docs/languages/go.md): structs with `encoding/json` tags, named types with
//! constants, union wrappers, and one function per operation, for the runtime module in
//! `runtimes/go`. Experimental.

pub mod external;
pub mod naming;
mod operations;
mod print;
mod vendor;

use tsurara_backend::{Backend, Emitted, Error, Markers};
use tsurara_lower::{Capabilities, Enums, Inheritance, lower};
use tsurara_sem::{Model, Options};

/// The first line of every generated file: the line Go tools recognize as generated.
pub const HEADER: &str = "// Code generated by tsurara. DO NOT EDIT.";

/// The version of the runtime module the generated code needs, recorded in `tsurara_gen.go` for
/// `tsurara check`.
pub const RUNTIME_VERSION: &str = "v0.1.0";

/// What Go can express (design.md 18.5.2, docs/languages/go.md).
pub const CAPABILITIES: Capabilities = Capabilities {
    inline_records: false,
    structural_unions: false,
    tagged_unions: true,
    intersections: false,
    inheritance: Inheritance::None,
    literal_types: false,
    enums: Enums::None,
    tuples: false,
    strict_decoding: false,
    nullable_primitives: true,
    recursion_by_value: false,
};

/// Options of the `go` section.
#[derive(Debug, Clone)]
pub struct GoOptions {
    /// The package name of the generated files.
    pub package: String,
    /// The import path of the runtime module.
    pub runtime_module: String,
    /// Emit mock values and routes for `tsuraratest` in `mocks_gen.go`, built with the tag
    /// `tsurara_mocks` (`go.mocks`).
    pub mocks: bool,
}

impl Default for GoOptions {
    fn default() -> Self {
        GoOptions {
            package: "api".into(),
            runtime_module: "github.com/tsurara-openapi/tsurara/runtimes/go".into(),
            mocks: false,
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Go {
    pub options: GoOptions,
}

impl Backend for Go {
    fn id(&self) -> &'static str {
        "go"
    }

    fn markers(&self) -> Markers {
        Markers {
            generated: HEADER.to_owned(),
            version: Some(tsurara_backend::VersionMarker {
                file: "tsurara_gen.go".into(),
                prefix: format!("// Requires {} ", self.options.runtime_module),
            }),
            sidecars: Vec::new(),
        }
    }

    fn emit(&self, model: &Model, opts: &Options) -> Result<Emitted, Error> {
        let (module, mut warnings) = lower(model, &CAPABILITIES);
        let (files, more, manifest) = print::print(model, &module, opts, &self.options);
        warnings.extend(more);
        Ok(Emitted {
            files,
            warnings,
            manifest: Some(manifest),
        })
    }

    fn options_json(&self) -> serde_json::Value {
        serde_json::json!({
            "package": self.options.package,
            "runtimeModule": self.options.runtime_module,
            "mocks": self.options.mocks,
        })
    }

    fn example(&self, input: &tsurara_backend::ExampleInput) -> Option<tsurara_backend::Example> {
        let (module, _) = lower(input.model, &CAPABILITIES);
        print::example(input.model, &module, input.opts, &self.options, input)
    }
}

/// Builds the model from a loaded definition and generates Go.
pub fn generate(
    set: &tsurara_loader::DocumentSet,
    opts: &Options,
    go: &GoOptions,
) -> Result<tsurara_backend::Output, Error> {
    tsurara_backend::generate(
        &Go {
            options: go.clone(),
        },
        set,
        opts,
    )
}
